//! Independently expected whole-account worn conversion matrices, not developer fixtures.
use gielinor_world::{equipment::{WearType,Event},inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,worn_item_swap::Rule,hits::{Hit,Target,Style},CoordGrid};
fn fixture(reverse:bool,member:bool,occupied:bool,holes:usize)->(World,ActorId,i32,i32,usize,usize){let(input,output,from,to)=if reverse{(29775,25644,5,3)}else{(25644,29775,3,5)};let mut w=World::default();w.collision.allocate(3200,3200,0);for(a,b,f,t)in[(25644,29775,3,5),(29775,25644,5,3)]{w.worn_item_swaps.insert(a,Rule{output:b,from_slot:f,to_slot:t,button_operation:2});w.wear_types.types.insert(a,WearType{primary:Some(f),secondary:[None,None],requirements:vec![]});}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);let mut d=PlayerData::new(1,"Independent worn hammer".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==4{input}else{1931},count:1,vars:0})).unwrap();}for s in(0..28).filter(|s|*s!=4).take(holes){d.inventory.restore_slot(s,None).unwrap();}d.equipment.restore_slot(from,Some(Item{id:input,count:1,vars:0})).unwrap();d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();if occupied{d.equipment.restore_slot(to,Some(Item{id:999,count:1,vars:9})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.tick().unwrap();w.drain_events();(w,a,input,output,from,to)}
#[test]fn one_hundred_forty_four_atomic_guard_and_metadata_refusals(){let mut n=0;for reverse in [false,true]{for member in [false,true]{for case in 0..36{let(mut w,a,input,output,from,to)=fixture(reverse,member,false,1);let mut claim=input;let mut slot=from;match case {
0=>claim=output,1=>slot=to,2=>{w.worn_item_swaps.remove(&input);},
3=>{w.data_mut(a).unwrap().equipment.restore_slot(from,None).unwrap();},
4=>{w.data_mut(a).unwrap().equipment.restore_slot(from,Some(Item{id:input,count:2,vars:0})).unwrap();},
5=>{w.data_mut(a).unwrap().equipment.restore_slot(from,Some(Item{id:input,count:1,vars:1})).unwrap();},
6=>{w.data_mut(a).unwrap().equipment.restore_slot(from,Some(Item{id:1931,count:1,vars:0})).unwrap();},
7=>{w.object_types.stackable.insert(input);},8=>{w.object_types.stackable.insert(output);},9=>{w.object_types.dummy.insert(input);},10=>{w.object_types.dummy.insert(output);},
11=>w.data_mut(a).unwrap().inventory.placeholders=true,12=>w.data_mut(a).unwrap().equipment.placeholders=true,
13=>w.data_mut(a).unwrap().inventory.stack=gielinor_world::inventory::StackType::Always,14=>w.data_mut(a).unwrap().equipment.stack=gielinor_world::inventory::StackType::Never,
15=>{w.wear_types.types.remove(&input);},16=>{w.wear_types.types.remove(&output);},17=>w.wear_types.types.get_mut(&input).unwrap().primary=Some(to),18=>w.wear_types.types.get_mut(&output).unwrap().primary=Some(from),19=>w.wear_types.types.get_mut(&input).unwrap().secondary=[Some(to),None],20=>w.wear_types.types.get_mut(&output).unwrap().secondary=[Some(from),None],
21=>w.set_modal_open(a,true).unwrap(),22=>w.delay_player(a,8).unwrap(),23=>w.request_logout(a).unwrap(),24=>{w.data_mut(a).unwrap().stats.set_current(3,0);},
25=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);},
26=>w.worn_item_swaps.get_mut(&input).unwrap().to_slot=from,27=>w.worn_item_swaps.get_mut(&input).unwrap().to_slot=14,28=>w.worn_item_swaps.get_mut(&input).unwrap().output=input,29=>w.worn_item_swaps.get_mut(&input).unwrap().output=-1,
30..=35=>{let id=if case%2==0{input}else{output};let t=gielinor_world::inventory::Template{link:id,template:799};match (case-30)/2{0=>{w.object_types.notes.insert(id,t);},1=>{w.object_types.placeholders.insert(id,t);},_=>{w.object_types.transforms.insert(id,t);}}},_=>unreachable!()}
if case!=23{w.data_mut(a).unwrap().inventory.clear_modified();w.data_mut(a).unwrap().equipment.clear_modified();}let before=w.data(a).unwrap().clone();w.drain_events();let _=w.submit(a,Action::SwapWornItem{slot,item:claim});for _ in 0..4{w.tick().unwrap();}let d=w.data(a).unwrap();assert_eq!(d.inventory,before.inventory,"r{reverse} m{member} case{case}");assert_eq!(d.equipment,before.equipment);assert_eq!(d.stats,before.stats);assert!(d.inventory.modified().is_empty());assert!(d.equipment.modified().is_empty());assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..}|WorldEvent::WearposEffects{..}|WorldEvent::WornEffects{..}|WorldEvent::EquipmentResult{result:Ok(_),..})));n+=1;}}}assert_eq!(n,144);println!("PG_WORN atomic refusals={n}");}
